// Demo tool implementations. Replace the bodies with real lookups (DB, calendar, CRM) as needed;
// the contract is: POST /webhook/tool with { tool, input, channel, phone }, respond with JSON.
const req = $input.first().json;
if (($env.TOOLS_SECRET || '') && req.headers['x-tools-secret'] !== $env.TOOLS_SECRET) {
  return [{ json: { status: 401, body: { error: 'unauthorized' } } }];
}
const name = req.body?.tool;
const input = req.body?.input || {};

const INFO = {
  hours: 'Monday to Friday 8am to 5pm, Saturday 8am to 1pm, closed Sunday and public holidays.',
  address: '12 Example Street, Rosebank, Johannesburg.',
  services: 'Consultations, standard service and premium service.',
  prices: 'Consultation R250, standard service R450, premium service R800.',
};

if (name === 'get_business_info') {
  const topic = input.topic || 'all';
  return [{ json: { status: 200, body: topic === 'all' ? INFO : { [topic]: INFO[topic] ?? 'Unknown topic.' } } }];
}

if (name === 'create_booking') {
  const missing = ['name', 'service', 'datetime'].filter(k => !input[k]);
  if (missing.length) return [{ json: { status: 200, body: { ok: false, error: `Missing ${missing.join(', ')}` } } }];
  const store = $getWorkflowStaticData('global');
  store.bookings = store.bookings || [];
  const reference = 'BK' + Date.now().toString(36).toUpperCase().slice(-5);
  store.bookings.push({ reference, ...input, createdAt: new Date().toISOString() });
  return [{ json: { status: 200, body: { ok: true, reference, ...input } } }];
}

return [{ json: { status: 404, body: { error: `Unknown tool ${name}` } } }];
